"""Module dependencies: call edges, pipe applications, and root-scoped plans.

Edges are stored prerequisite-first: ``add_edge(a, b)`` means "a must be
compiled before b".  A call pair ``[caller, callee]`` therefore contributes
``callee -> caller``; a pipe contributes ``filter -> target``.  All call and
pipe edges together form a DAG, so a root-scoped compile is a closure over
prerequisites followed by Kahn ordering that breaks every tie with the
lexicographically smallest currently eligible module name.

Pipes are local to their target and a filter's own pipes apply transitively
through composed bindings, so one entry sees a flattened list of composed
filter applications: each maps the filter's own parameter names to entry
parameter names.
"""

from collections import defaultdict, deque
from heapq import heapify, heappop, heappush
from typing import Dict, List, Tuple


class DependencyGraph:
    """Call and pipe dependencies between model names."""

    def __init__(self, models: Dict[str, object] = None):
        self.graph = defaultdict(list)        # prerequisite -> dependents
        self.dependencies = defaultdict(list)  # dependent -> prerequisites
        self.filter_functions: List[str] = []
        self.pipes: Dict[str, List[Tuple[str, Dict[str, str]]]] = defaultdict(list)
        self.models = models if models is not None else {}
        self.model_to_node: Dict[str, int] = {}
        self.node_to_model: Dict[int, str] = {}
        self.nodes = 0

    # -- node/edge construction ---------------------------------------------
    def add_node(self, model):
        if model in self.model_to_node:
            return self.model_to_node[model]
        self.model_to_node[model] = self.nodes
        self.node_to_model[self.nodes] = model
        self.nodes += 1
        return self.model_to_node[model]

    def add_edge(self, prerequisite, dependent):
        self.add_node(prerequisite)
        self.add_node(dependent)
        if prerequisite in self.dependencies[dependent]:
            return                       # duplicate pairs have no extra effect
        self.dependencies[dependent].append(prerequisite)
        self.graph[prerequisite].append(dependent)

    def Edge(self, model1, model2):
        """Deprecated spelling kept for callers: model1 precedes model2."""
        self.add_edge(model1, model2)

    def CallEdge(self, model, dependency_models: List):
        """Register ``[caller, callee]`` pairs: callees precede their caller."""
        for dependency in dependency_models:
            self.add_edge(dependency, model)

    def Pipe(self, target, filter, bind=None):
        """Register one pipe application; its filter precedes its target."""
        self.add_node(target)
        self.add_node(filter)
        if filter not in self.filter_functions:
            self.filter_functions.append(filter)
        self.pipes[target].append((filter, dict(bind or {})))
        self.add_edge(filter, target)

    def Node(self, model):
        """Create a new node in the dependency graph."""
        return self.add_node(model)

    # -- traversal ----------------------------------------------------------
    def prerequisites(self, root) -> set:
        """The root plus every transitive call/pipe prerequisite."""
        seen = {root}
        stack = [root]
        while stack:
            node = stack.pop()
            for prereq in self.dependencies[node]:
                if prereq not in seen:
                    seen.add(prereq)
                    stack.append(prereq)
        return seen

    def compile_order(self, root) -> List[str]:
        """Root-scoped prerequisites-first order, ties by smallest name."""
        del self.topologicalSortUtil  # replaced by the iterative ordering below
        seen = self.prerequisites(root)
        pending = {node: 0 for node in seen}
        for node in seen:
            for prereq in self.dependencies[node]:
                if prereq in seen:
                    pending[node] += 1
        ready = [node for node in seen if pending[node] == 0]
        heapify(ready)
        order: List[str] = []
        while ready:
            node = heappop(ready)
            order.append(node)
            for dependent in self.graph[node]:
                if dependent in pending:
                    pending[dependent] -= 1
                    if pending[dependent] == 0:
                        heappush(ready, dependent)
        if len(order) != len(seen):        # pragma: no cover - acyclic by input
            raise ValueError("dependency cycle at " + str(root))
        return order

    def applications(self, root) -> List[Tuple[str, Dict[str, str]]]:
        """Compose every filter application visible from one entry root.

        Each item is ``(filter, mapping)`` where ``mapping`` names the entry
        parameter that supplies the corresponding filter parameter.  Reusing a
        filter with different bindings yields different applications, and a
        filter's own pipes are flattened using the composed bindings.
        """
        results: List[Tuple[str, Dict[str, str]]] = []
        queue = deque()
        queue.append((root, self.identity_binding(root)))
        while queue:
            target, upstream = queue.popleft()
            for filter, bind in self.pipes.get(target, ()):
                composed = {parameter: upstream[bound] for parameter, bound in bind.items()}
                results.append((filter, composed))
                queue.append((filter, composed))
        return results

    def identity_binding(self, module) -> Dict[str, str]:
        """Every parameter of ``module`` is supplied by itself."""
        model = self.models.get(module)
        if model is None:
            return {}
        return {parameter.name: parameter.name for parameter in model.inputs}

    def has_direct_pipe(self, target) -> bool:
        return bool(self.pipes.get(target))


def topological_sort(graph) -> List:      # pragma: no cover - legacy helper
    """Deterministic whole-graph ordering, retained for API compatibility."""
    pending = {node: len(prereqs) for node, prereqs in graph.dependencies.items()}
    ready = [node for node, degree in pending.items() if degree == 0]
    heapify(ready)
    order = []
    while ready:
        node = heappop(ready)
        order.append(node)
        for dependent in graph.graph[node]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heappush(ready, dependent)
    return order
